import numpy as np
import pandas as pd
from scipy.spatial.distance import cdist

S = pd.read_csv('/app/dataset/stations.csv').set_index('station_id')
R = pd.read_csv('/app/dataset/readings.csv')
WS = pd.read_csv('/app/dataset/weather_stations.csv').set_index('weather_station_id')
WR = pd.read_csv('/app/dataset/weather_readings.csv')
S['pollutant'] = R.groupby('station_id').pollutant.first()
X = R.pivot(index='timestamp', columns='station_id', values='current_reading')
Z = X.interpolate(limit_direction='both')
VARS = ['temperature_c', 'humidity_pct', 'wind_speed_m_s', 'rain_accumulation_mm']
W = {v: WR.pivot(index='timestamp', columns='weather_station_id', values=v) for v in VARS}
DIST = pd.DataFrame(cdist(S[['latitude', 'longitude']].values * [1, .63], WS[['latitude', 'longitude']].values * [1, .63]), index=S.index, columns=WS.index)


def residual(y, x):
    x = np.asarray(x)
    if x.ndim == 1:
        x = x[:, None]
    a = np.column_stack([np.ones(len(y)), x])
    return y - a @ np.linalg.lstsq(a, y, rcond=None)[0]


def peer(j, method='median'):
    ids = S.index[(S.district == S.loc[j, 'district']) & (S.pollutant == S.loc[j, 'pollutant']) & (S.index != j)]
    return getattr(Z[ids], method)(axis=1)


def weather(j, mode):
    ids = WS.index[WS.district == S.loc[j, 'district']]
    if mode == 'district':
        return pd.DataFrame({v: W[v][ids].mean(axis=1) for v in VARS})
    if mode == 'nearest_district':
        ids = [DIST.loc[j, ids].idxmin()]
    elif mode == 'nearest':
        ids = [DIST.loc[j].idxmin()]
    elif mode == 'weighted':
        weights = 1 / (DIST.loc[j] + .001) ** 2
        weights /= weights.sum()
        return pd.DataFrame({v: W[v].mul(weights).sum(axis=1) for v in VARS})
    return pd.DataFrame({v: W[v][ids].mean(axis=1) for v in VARS})


if __name__ == '__main__':
    out = []
    for j in S.index:
        y = Z[j].values
        p = peer(j).values
        e = residual(y, p)
        for mode in ['district', 'nearest', 'nearest_district', 'weighted']:
            w = weather(j, mode)
            for v in VARS:
                ew = residual(w[v].values, p)
                c = np.corrcoef(e, ew)[0, 1] if ew.std() > 1e-8 else 0
                out.append({'station_id': j, 'district': S.loc[j, 'district'], 'pollutant': S.loc[j, 'pollutant'], 'mode': mode, 'driver': v, 'partial_corr': c, 'resid_sd': e.std(), 'slope': np.dot(e, ew) / np.dot(ew, ew) if ew.std() > 1e-8 else 0})
    out = pd.DataFrame(out)
    out['abs_corr'] = out.partial_corr.abs()
    out.to_csv('/app/weather_residuals.csv', index=False)
    for mode in out['mode'].unique():
        print('\nWEATHER MODE', mode)
        print(out[out['mode'] == mode].sort_values('abs_corr', ascending=False).head(15).round(3).to_string(index=False))

